            elif kind == "p":
                parts.append(render(payload))
            elif kind == "raw":
                parts.append(payload)
            elif kind == "table":
                parts.append(TABLES[payload]())
    text = "\n\n".join(parts)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text


if __name__ == "__main__":
