    print(json.dumps({"chars_total": len(txt), "chars_chinese": cn,
                      "tables_defined": len(TABLES),
                      "placeholders_left": len(re.findall(r"\{[NTCRGB]:", txt))},
                     ensure_ascii=False, indent=2))
